/// Compare each resolved package's registry integrity against the
/// checksum the wanted lockfile recorded for the same `name@version`,
/// returning the first `(package, expected, actual)` triple that
/// disagrees. `expected` is the lockfile-recorded value; `actual` is
/// what the registry currently serves. Returns `None` when every entry
/// matches, when there's no wanted lockfile, or when it records no
/// checksums to compare against.
///
/// Only registry-served tarball resolutions are compared — git-hosted
/// tarballs and directory / git / binary resolutions aren't addressed
/// by a registry checksum, and a package absent from the lockfile's
/// `packages:` map has nothing to compare and is left to the normal
/// resolve path. Checksums are compared by their canonical string form
/// so a hand-edited or stale hash is caught regardless of how it was
/// written.
fn find_lockfile_checksum_mismatch(
    graph: &pacquet_resolving_deps_resolver::DependenciesGraph,
    wanted_lockfile: Option<&Lockfile>,
) -> Option<(String, String, String)> {
    let packages = wanted_lockfile?.packages.as_ref()?;
    let locked: HashMap<String, String> = packages
        .iter()
        .filter_map(|(key, metadata)| {
            let integrity = metadata.resolution.integrity()?;
            Some((key.without_peer().to_string(), integrity.to_string()))
        })
        .collect();
    for node in graph.values() {
        let pacquet_lockfile::LockfileResolution::Tarball(tarball) =
            &node.resolve_result.resolution
        else {
            continue;
        };
        if tarball.git_hosted == Some(true) {
            continue;
        }
        let (Some(resolved), Some(name_ver)) =
            (tarball.integrity.as_ref(), node.resolve_result.name_ver.as_ref())
        else {
            continue;
        };
        let resolved = resolved.to_string();
        if let Some(expected) = locked.get(&name_ver.to_string())
            && *expected != resolved
        {
            return Some((name_ver.to_string(), expected.clone(), resolved));
        }
    }
